it","pose":350,"notes":["Uw à relever sur fiche technique fabricant","Sw à relever sur fiche technique fabricant","Prix de fourniture absent de la source","La source indique une puissance en kW : donnée incohérente pour une menuiserie, à corriger"]}]$products$::jsonb) LOOP
    SELECT id INTO v_id FROM public.catalogue_produits
    WHERE (COALESCE(p->>'reference','') <> '' AND reference = p->>'reference')
       OR lower(trim(nom)) = lower(trim(p->>'nom'))
    ORDER BY CASE WHEN reference = p->>'reference' THEN 0 ELSE 1 END
    LIMIT 1;
    IF v_id IS NULL THEN
      INSERT INTO public.catalogue_produits (
        entreprise_id,categorie,nom,marque,reference,description,caracteristiques,
        prix_unitaire_ht,unite,tva_taux,eligible_mpr,eligible_cee,fiche_cee,actif,
        public_cible,catalogue_groupe,forfait_pose_ht,forfait_evacuation_ht
      ) VALUES (
        v_entreprise,p->>'categorie',p->>'nom',COALESCE(p->>'marque',''),p->>'reference',
        p->>'description',COALESCE(p->'caracteristiques','{}'::jsonb),
        COALESCE(NULLIF(p->>'prix_ht','')::numeric,0),COALESCE(p->>'unite','unite'),COALESCE(NULLIF(p->>'tva','')::numeric,5.5),
        false,COALESCE((p->>'eligible_cee')::boolean,false),COALESCE(p->>'fiche_cee',''),true,
        'particulier','particulier',COALESCE(NULLIF(p->>'pose','')::numeric,0),0
      );
    ELSE
      UPDATE public.catalogue_produits SET
        categorie=p->>'categorie', nom=p->>'nom', marque=COALESCE(NULLIF(p->>'marque',''),marque),
        reference=p->>'reference', description=p->>'description',
        caracteristiques=COALESCE(caracteristiques,'{}'::jsonb) || COALESCE(p->'caracteristiques','{}'::jsonb),
        prix_unitaire_ht=COALESCE(NULLIF(p->>'prix_ht','')::numeric,0),
        unite=COALESCE(NULLIF(p->>'unite',''),unite), tva_taux=COALESCE(NULLIF(p->>'tva','')::numeric,tva_taux),
        eligible_mpr=false, eligible_cee=COALESCE((p->>'eligible_cee')::boolean,false),
        fiche_cee=COALESCE(p->>'fiche_cee',''), actif=true,
        public_cible='particulier', catalogue_groupe='particulier',
        forfait_pose_ht=COALESCE(NULLIF(p->>'pose','')::numeric,0), forfait_evacuation_ht=0
      WHERE id=v_id;
    END IF;
    v_id := NULL;
  END LOOP;
END $$;

-- ITE : l'isolant, l'échafaudage, l'enduit et la pose restent des lignes distinctes.
UPDATE public.catalogue_produits SET
  categorie='ite', public_cible='particulier', catalogue_groupe='particulier', actif=true,
  prix_unitaire_ht=24, unite='m2', forfait_pose_ht=0, forfait_evacuation_ht=0,
